SELECT 'silicone kitchen' AS seed, p.asin, p.product_name, p.manufacturer, p.stock FROM product_search JOIN products p ON p.rowid=product_search.rowid WHERE product_search MATCH '"silicone"* AND ("kitchen"* OR "cooking"*)' AND p.tenant='itg' LIMIT 5;
